// Deterministic CLDR49 production data compiler. Inputs are official CLDR/UCD.
// It never opens ICU or obtains production collation elements from an oracle.
#define SOUNIO_CLDR_BUILD_NO_MAIN
#include "cldr_build.cpp"
#include "cldr_locale.hpp"
using Cbytes=std::vector<std::uint8_t>;
void cput(Cbytes&out,std::uint64_t value,unsigned width=4){if(width<8&&value>=(std::uint64_t{1}<<(width*8)))bad("CLDR binary integer extent");for(unsigned i=0;i<width;++i)out.push_back(static_cast<std::uint8_t>(value>>(8*i)));}
void cpatch(Cbytes&out,std::size_t at,std::uint64_t value){if(at>out.size()||out.size()-at<4||value>0xffffffffU)bad("CLDR binary patch extent");for(unsigned i=0;i<4;++i)out[at+i]=static_cast<std::uint8_t>(value>>(8*i));}
std::uint32_t csmall(std::size_t n){if(n>0xffffffffU)bad("CLDR binary count overflow");return static_cast<std::uint32_t>(n);}
struct Csection{unsigned id,width;Cbytes bytes;std::uint32_t count()const{if(!width||bytes.size()%width)bad("CLDR section width");return csmall(bytes.size()/width);}};
struct Cdata{
 std::array<Csection,12> sections{{{1,1,{}},{2,4,{}},{3,32,{}},{4,28,{}},{5,64,{}},{6,32,{}},{7,8,{}},{8,8,{}},{9,24,{}},{10,16,{}},{11,20,{}},{12,16,{}}}};
 std::map<std::string,std::pair<std::uint32_t,std::uint32_t>> strings;
 std::map<Fseq,std::uint32_t> scalar_sequences;
 std::map<std::vector<std::array<std::uint64_t,5>>,std::uint32_t> ce_sequences;
 std::uint32_t root_count=0;
 std::pair<std::uint32_t,std::uint32_t> string(const std::string&s){auto prior=strings.find(s);if(prior!=strings.end())return prior->second;auto at=sections[0].count();sections[0].bytes.insert(sections[0].bytes.end(),s.begin(),s.end());auto value=std::pair(at,csmall(s.size()));strings.emplace(s,value);return value;}
 void string_fields(Cbytes&out,const std::string&s){auto[at,n]=string(s);cput(out,at);cput(out,n);}
 std::uint32_t scalars(const Fseq&s){auto prior=scalar_sequences.find(s);if(prior!=scalar_sequences.end())return prior->second;auto at=sections[1].count();for(auto cp:s)cput(sections[1].bytes,cp);scalar_sequences.emplace(s,at);return at;}
 std::uint32_t ces(const Gces&input,const Fbuilder&b,const std::array<std::vector<std::uint64_t>,4>&weights){std::vector<std::array<std::uint64_t,5>> normalized;for(const auto&ce:input)normalized.push_back({weights[0].at(ce.w[0]),weights[1].at(ce.w[1]),weights[2].at(ce.w[2]),weights[3].at(ce.w[3]),ce.casing});auto prior=ce_sequences.find(normalized);if(prior!=ce_sequences.end())return prior->second;auto at=sections[2].count();for(const auto&ce:normalized){cput(sections[2].bytes,ce[0],8);cput(sections[2].bytes,ce[1],8);cput(sections[2].bytes,ce[2],8);cput(sections[2].bytes,ce[3]);cput(sections[2].bytes,ce[4]);}ce_sequences.emplace(std::move(normalized),at);(void)b;return at;}
 void entry(const Fkey&key,const Gces&value,const Fbuilder&b,const std::array<std::vector<std::uint64_t>,4>&weights,bool removed=false){auto&out=sections[3].bytes;cput(out,scalars(key.text));cput(out,key.text.size());cput(out,scalars(key.prefix));cput(out,key.prefix.size());cput(out,ces(value,b,weights));cput(out,value.size());cput(out,removed?1:0);}
 void root(const Fbuilder&b){std::array<std::vector<std::uint64_t>,4> w;for(unsigned i=0;i<4;++i)w[i]=b.order[i].weights();for(const auto&[key,value]:b.root_mappings)entry(key,value,b,w);root_count=sections[3].count();for(const auto&[cp,rank]:b.han_ranks){cput(sections[7].bytes,cp);cput(sections[7].bytes,rank);}}
 void locale(const Tailoring&t,const Fbuilder&b,std::size_t source_index){
  std::array<std::vector<std::uint64_t>,4>w;for(unsigned i=0;i<4;++i)w[i]=b.order[i].weights();auto first=sections[3].count();std::map<Fkey,std::pair<Gces,bool>> delta;for(const auto&[key,value]:b.mappings){auto root=b.root_mappings.find(key);if(root==b.root_mappings.end()||!b.same(root->second,value))delta.emplace(key,std::pair(value,false));}for(const auto&[key,value]:b.root_mappings)if(!b.mappings.contains(key)){(void)value;delta.emplace(key,std::pair(Gces{},true));}for(const auto&[key,value]:delta)entry(key,value.first,b,w,value.second);
  auto count=sections[3].count()-first;auto settings_id=sections[5].count();auto&settings=sections[5].bytes;cput(settings,b.settings.strength);cput(settings,b.settings.shifted);cput(settings,b.settings.backwards);cput(settings,b.settings.case_level);cput(settings,b.settings.case_first);const std::map<std::string,unsigned> variable{{"space",0},{"punct",1},{"symbol",2},{"currency",3}};auto variable_id=variable.find(b.settings.max_variable);if(variable_id==variable.end())bad("unsupported maxVariable");cput(settings,variable_id->second);auto group_first=sections[6].count();Ggroups groups(b);for(const auto&[start,name]:groups.starts){cput(sections[6].bytes,start);auto found=groups.rank.find(name);if(found==groups.rank.end())bad("missing binary reorder group");cput(sections[6].bytes,found->second);}cput(settings,group_first);cput(settings,sections[6].count()-group_first);
  auto&record=sections[4].bytes;string_fields(record,t.locale);string_fields(record,t.type);string_fields(record,t.variant);cput(record,first);cput(record,count);cput(record,settings_id);cput(record,1);cput(record,source_index);cput(record,1);for(unsigned i=0;i<4;++i)cput(record,0);
 }
 void registry(const ClocaleRegistry&r){std::set<std::string> locales;for(const auto&[locale,type]:r.defaults){(void)type;locales.insert(locale);}for(const auto&[locale,parent]:r.parents){locales.insert(locale);locales.insert(parent);}for(const auto&locale:locales){auto&out=sections[8].bytes;string_fields(out,locale);auto def=r.defaults.find(locale);string_fields(out,def==r.defaults.end()?"":def->second);auto parent=r.parents.find(locale);string_fields(out,parent==r.parents.end()?"":parent->second);}for(const auto&[alias,type]:r.type_aliases){auto&out=sections[9].bytes;string_fields(out,alias);string_fields(out,type);}unsigned kind=0;for(const auto*aliases:{&r.language_aliases,&r.script_aliases,&r.territory_aliases,&r.variant_aliases}){++kind;for(const auto&[from,to]:*aliases){auto&out=sections[10].bytes;cput(out,kind);string_fields(out,from);string_fields(out,Cparts::lower(to));}}for(const auto&[from,to]:r.likely){auto&out=sections[11].bytes;string_fields(out,from);string_fields(out,Cparts::lower(to));}}
 Cbytes finish(std::ostream&report)const{Cbytes out={'S','O','U','N','C','L','D','1'};cput(out,2);cput(out,0x00120000);cput(out,49);cput(out,sections.size());cput(out,root_count);cput(out,1);auto directory=out.size();out.resize(out.size()+sections.size()*16);for(std::size_t i=0;i<sections.size();++i){const auto&s=sections[i];while(out.size()%8)out.push_back(0);cpatch(out,directory+i*16,s.id);cpatch(out,directory+i*16+4,s.width);cpatch(out,directory+i*16+8,s.count());cpatch(out,directory+i*16+12,csmall(out.size()));report<<"section\t"<<s.id<<'\t'<<s.width<<'\t'<<s.count()<<'\t'<<out.size()<<'\n';out.insert(out.end(),s.bytes.begin(),s.bytes.end());}if(out.size()>24U*1024*1024)bad("CLDR asset exceeds explicit24MiB data budget");report<<"bytes\t"<<out.size()<<"\nformat\t2\nuca\t18.0.0\ncldr\t49\nroot_entries\t"<<root_count<<"\npublic_locales\t"<<sections[4].count()<<"\n";return out;}
};
int main(int argc,char**argv){try{if(argc!=5)return 64;cldr_input_versions(argv[1],argv[2]);Fractional f(fs::path(argv[1])/"common/uca/FractionalUCA.txt");Fnormalize n(argv[2]);ClocaleRegistry r(argv[1]);for(std::size_t i=0;i<r.entries.size();++i){const auto&t=r.entries[i];if(t.type.starts_with("private-")||!t.variant.empty())continue;if(r.resolve_request(t.locale,t.type)!=i)bad("public locale canonical reachability");}Cdata out;{Fbuilder root(f,n);out.root(root);}for(std::size_t i=0;i<r.entries.size();++i){const auto&t=r.entries[i];if(t.type.starts_with("private-")||!t.variant.empty())continue;Fbuilder b(f,n);b.apply(r,i);out.locale(t,b,i);}out.registry(r);std::ofstream report(argv[4]);auto data=out.finish(report);std::ofstream binary(argv[3],std::ios::binary);binary.write(reinterpret_cast<const char*>(data.data()),static_cast<std::streamsize>(data.size()));if(!binary||!report)bad("CLDR binary output");std::cout<<"CLDR_LOCALE_DATA_GENERATOR_OK bytes="<<data.size()<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"CLDR_LOCALE_DATA_GENERATOR_ERROR "<<e.what()<<"\n";return 1;}}

